const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表' },
      { kind: 'text', payload: '物理量' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '换算结果' },
      { kind: 'text', payload: '速度' },
      { kind: 'text', payload: '126 ÷ 3.6' },
      { kind: 'text', payload: '35.0 m/s' },
      { kind: 'text', payload: '126 km/h = 126 ÷ 3.6 m/s = 35.0 m/s' },
      { kind: 'text', payload: '依据：1 m/s = 3.6 km/h，故 km/h → m/s 需除以 3.6；结果保留三位有效数字' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var pad = Math.round(Math.max(24, W * 0.06));
    var tableX = pad;
    var tableW = W - 2 * pad;
    var w0 = Math.round(tableW * 0.26);
    var w1 = Math.round(tableW * 0.37);
    var cx = [tableX, tableX + w0, tableX + w0 + w1, tableX + tableW];
    var titleY = pad + 22;
    var headerY = pad + 52;
    var headerH = 44;
    var dataY = headerY + headerH;
    var dataH = 58;

    function rect(x, y, w, h) {
      return [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']];
    }

    var t = 2;
    var paths = [
      { id: 'bodyBg', commands: rect(tableX, dataY, tableW, dataH) },
      { id: 'headBg', commands: rect(tableX, headerY, tableW, headerH) },
      { id: 'borderTop', commands: rect(tableX, headerY, tableW, t) },
      { id: 'borderBottom', commands: rect(tableX, dataY + dataH - t, tableW, t) },
      { id: 'borderLeft', commands: rect(tableX, headerY, t, headerH + dataH) },
      { id: 'borderRight', commands: rect(tableX + tableW - t, headerY, t, headerH + dataH) },
      { id: 'divRow', commands: rect(tableX, dataY - t / 2, tableW, t) },
      { id: 'divV1', commands: rect(cx[1] - t / 2, headerY, t, headerH + dataH) },
      { id: 'divV2', commands: rect(cx[2] - t / 2, headerY, t, headerH + dataH) }
    ];
    var ink = '#26354a';
    var fills = {
      bodyBg: '#ffffff',
      headBg: '#e8eef6',
      borderTop: ink,
      borderBottom: ink,
      borderLeft: ink,
      borderRight: ink,
      divRow: ink,
      divV1: ink,
      divV2: ink
    };

    var children = [];
    var i;
    for (i = 0; i < paths.length; i++) {
      children.push({ type: 'path', pathId: paths[i].id, fill: fills[paths[i].id] });
    }

    function label(idx, x, y, hAlign, vAlign) {
      return {
        type: 'label',
        contentId: metrics[idx].contentId,
        anchor: { x: x, y: y },
        hAlign: hAlign,
        vAlign: vAlign,
        color: ink
      };
    }

    var hc = [(cx[0] + cx[1]) / 2, (cx[1] + cx[2]) / 2, (cx[2] + cx[3]) / 2];
    var hy = headerY + headerH / 2;
    var dy = dataY + dataH / 2;

    children.push(label(0, W / 2, titleY, 'center', 'middle'));
    children.push(label(1, hc[0], hy, 'center', 'middle'));
    children.push(label(2, hc[1], hy, 'center', 'middle'));
    children.push(label(3, hc[2], hy, 'center', 'middle'));
    children.push(label(4, hc[0], dy, 'center', 'middle'));
    children.push(label(5, hc[1], dy, 'center', 'middle'));
    children.push(label(6, hc[2], dy, 'center', 'middle'));
    children.push(label(7, tableX, dataY + dataH + 32, 'left', 'middle'));
    children.push(label(8, tableX, dataY + dataH + 62, 'left', 'middle'));

    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
